/** The change one operation made, or undefined when the file is byte-identical before and after. */
export function describeChange(displayPath: string, before: FileSnapshot, after: FileSnapshot): FileChange | undefined {
  if (before.state === "absent" && after.state === "absent") return undefined;
  if (before.state === "text" && after.state === "text" && before.content === after.content) return undefined;
  const kind: FileChange["kind"] = before.state === "absent" ? "added" : after.state === "absent" ? "deleted" : "modified";
